for w,g,b in [('madame-monsieur','Выбрано формальное обращение без имени конкретного адресата.','Дружеское приветствие и прощание не выполняют нужную роль в этом начале письма.'),('destinataire','Назван получатель сообщения.','Дата и подпись — другие сведения, а не получатель.'),('je-vous-ecris-au-sujet-de','Тема письма названа прямо.','Подтверждение времени и прощание не обозначают предмет обращения.'),('objet-message','Строка темы называет неисправность отопления.','Обращение и благодарность выполняют другие функции.'),('je-vous-prie-de','Выражена просьба уточнить дату.','Подтверждение даты и личная оценка не заменяют просьбу.'),('cordialement','Выбрано нейтральное деловое завершение.','Приветствие и строка темы не завершают письмо в нужном регистре.'),('reponse','Благодарность относится к полученному ответу.','Подтверждение визита и строка темы не выражают такую благодарность.')]:W[w]['review_items'][1]['feedback']=fb(g,b)

